<?php $p = $state['page']; $edit_locale = $this->input->get('edit') === 'ar' ? 'ar' : 'en'; $slug = $p['code'] === 'for-hotels' ? 'hotels' : $p['slug_' . $edit_locale]; $preview = $p['status'] === 'published' ? base_url($edit_locale . ($slug !== '' ? '/' . $slug : '')) : hkp_url('cms/preview/' . $p['id']) . '?edit=' . $edit_locale; ?>
<div class="hkp-head"><div><div class="hkp-eyebrow"><?php echo hkp_e('Website · Live editor'); ?></div><h1><?php echo hkp_h($state['payload']['tr']['en']['title'] ?: $p['code']); ?></h1><p><?php echo hkp_e('Edit safely beside the real page. Draft changes stay private until you publish.'); ?></p></div><div class="hkp-actions"><a class="hkp-btn hkp-btn--ghost" href="<?php echo hkp_url('cms/page/' . $p['id']); ?>"><?php echo hkp_e('SEO & revisions'); ?></a><button class="hkp-btn hkp-btn--ghost" type="button" id="live-save"><?php echo hkp_e('Save draft'); ?></button><?php if ($this->ha_auth->has('cms_pages.publish')): ?><button class="hkp-btn" type="button" id="live-publish"><?php echo hkp_e('Publish'); ?></button><?php endif; ?></div></div>
<div id="live-editor" class="studio-editor" data-url="<?php echo hkp_url('cms/live_save/' . $p['id']); ?>" data-preview="<?php echo hkp_h($preview); ?>" data-page="<?php echo (int) $p['id']; ?>" data-version="<?php echo (int) $state['version']; ?>" data-hash="<?php echo hkp_h($state['base_hash']); ?>" data-locale="<?php echo $edit_locale; ?>">
<section class="hkp-card studio-editor-controls"><div class="studio-section-head"><h2><?php echo hkp_e('Page & sections'); ?></h2><select id="live-locale" class="hkp-select" aria-label="<?php echo hkp_e('Editing language'); ?>"><option value="en"<?php echo $edit_locale === 'en' ? ' selected' : ''; ?>>EN</option><option value="ar"<?php echo $edit_locale === 'ar' ? ' selected' : ''; ?>>AR</option></select></div><p id="live-status" role="status" aria-live="polite" class="studio-save-status"><?php echo $state['version'] ? hkp_e('Private draft available') : hkp_e('No draft changes'); ?></p><div id="live-fields"></div><div class="hkp-field"><label for="live-add-type"><?php echo hkp_e('Add section'); ?></label><select id="live-add-type" class="hkp-select"><?php foreach ($types as $type => $info): ?><option value="<?php echo hkp_h($type); ?>"><?php echo hkp_e($info[0]); ?></option><?php endforeach; ?></select></div><button type="button" class="hkp-btn hkp-btn--ghost" id="live-add"><?php echo hkp_e('Add section'); ?></button></section>
<div class="studio-preview-wrap" id="live-preview-wrap"><div class="hkp-actions" style="justify-content:center;margin-bottom:12px"><button type="button" class="hkp-btn hkp-btn--ghost" data-live-device="desktop"><?php echo hkp_e('Desktop'); ?></button><button type="button" class="hkp-btn hkp-btn--ghost" data-live-device="tablet"><?php echo hkp_e('Tablet'); ?></button><button type="button" class="hkp-btn hkp-btn--ghost" data-live-device="mobile"><?php echo hkp_e('Mobile'); ?></button><a href="<?php echo hkp_h($preview); ?>" class="hkp-btn hkp-btn--ghost" target="_blank" rel="noopener"><?php echo hkp_e('Open website'); ?></a></div><iframe id="live-preview" class="studio-preview-frame" title="<?php echo hkp_e('Live website preview'); ?>" src="<?php echo hkp_h($preview . (strpos($preview, '?') === false ? '?' : '&') . 'studio_preview=' . $p['id']); ?>"></iframe></div></div>
<script type="application/json" id="live-payload"><?php echo json_encode($state['payload'], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_UNICODE); ?></script><script type="application/json" id="live-types"><?php echo json_encode($types, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?></script><script src="<?php echo hkp_asset('assets/hkp/live-editor.js'); ?>" defer></script>
